%[text] # Week 11: FEM Comparison — Linear vs Quadratic, Explicit vs Implicit
%[text] Side-by-side comparison of all four method combinations on the 1D transient heat equation.
%%
%[text] ## Problem Setup

L       = 1.0;
t_final = 0.1;

u_exact = @(x,t) exp(-pi^2*t) .* sin(pi*x);
u_init  = @(x) sin(pi*x);
%%
%[text] ## Helper: Linear FEM Solver

function [xN, U, dt, Nt, err] = solve_linear(L, t_final, nel, u_init, u_exact, method)
    nn = nel + 1;
    xN = linspace(0, L, nn).';
    he = L / nel;

    K      = zeros(nn);
    M      = zeros(nn);
    M_diag = zeros(nn, 1);

    for e = 1:nel
        nd = [e, e+1];
        K(nd,nd)      = K(nd,nd)      + (1/he)*[1 -1; -1 1];
        M(nd,nd)      = M(nd,nd)      + (he/6)*[2 1; 1 2];
        M_diag(nd)    = M_diag(nd)    + [he/2; he/2];
    end

    U = u_init(xN);
    U(1) = 0; U(end) = 0;

    if strcmp(method, 'explicit')
        dt = 0.8 * he^2 / 2;
        Nt = ceil(t_final / dt);
        dt = t_final / Nt;
        for n = 1:Nt
            U = U + dt * ((-K*U) ./ M_diag);
            U(1) = 0; U(end) = 0;
        end
    else
        dt = 0.01;
        Nt = round(t_final / dt);
        dt = t_final / Nt;
        A = M + dt*K;
        A(1,:) = 0; A(1,1) = 1;
        A(end,:) = 0; A(end,end) = 1;
        for n = 1:Nt
            rhs = M*U; rhs(1) = 0; rhs(end) = 0;
            U = A \ rhs;
        end
    end

    err = max(abs(U - u_exact(xN, t_final)));
end
%%
%[text] ## Helper: Quadratic FEM Solver

function [xN, U, dt, Nt, err] = solve_quadratic(L, t_final, nel, u_init, u_exact, method)
    nn = 2*nel + 1;
    xN = linspace(0, L, nn).';
    conn = [(1:2:2*nel-1).', (2:2:2*nel).', (3:2:2*nel+1).'];

    K      = zeros(nn);
    M      = zeros(nn);
    M_diag = zeros(nn, 1);

    for e = 1:nel
        nd = conn(e,:);
        he = xN(nd(3)) - xN(nd(1));

        K(nd,nd)   = K(nd,nd)   + (1/(3*he))*[7 -8 1; -8 16 -8; 1 -8 7];
        M(nd,nd)   = M(nd,nd)   + (he/30)*[4 2 -1; 2 16 2; -1 2 4];
        M_diag(nd) = M_diag(nd) + [he/6; 2*he/3; he/6];
    end

    U = u_init(xN);
    U(1) = 0; U(end) = 0;

    if strcmp(method, 'explicit')
        he = L / nel;
        dt = 0.8 * he^2 / 7;
        Nt = ceil(t_final / dt);
        dt = t_final / Nt;
        for n = 1:Nt
            U = U + dt * ((-K*U) ./ M_diag);
            U(1) = 0; U(end) = 0;
        end
    else
        dt = 0.01;
        Nt = round(t_final / dt);
        dt = t_final / Nt;
        A = M + dt*K;
        A(1,:) = 0; A(1,1) = 1;
        A(end,:) = 0; A(end,end) = 1;
        for n = 1:Nt
            rhs = M*U; rhs(1) = 0; rhs(end) = 0;
            U = A \ rhs;
        end
    end

    err = max(abs(U - u_exact(xN, t_final)));
end
%%
%[text] ## Run All Four Cases

nel_lin  = 20;   % 21 nodes
nel_quad = 10;   % 21 nodes

[x_LE, U_LE, dt_LE, Nt_LE, err_LE] = solve_linear(L, t_final, nel_lin, u_init, u_exact, 'explicit');
[x_LI, U_LI, dt_LI, Nt_LI, err_LI] = solve_linear(L, t_final, nel_lin, u_init, u_exact, 'implicit');
[x_QE, U_QE, dt_QE, Nt_QE, err_QE] = solve_quadratic(L, t_final, nel_quad, u_init, u_exact, 'explicit');
[x_QI, U_QI, dt_QI, Nt_QI, err_QI] = solve_quadratic(L, t_final, nel_quad, u_init, u_exact, 'implicit');

fprintf('%-28s  %10s  %6s  %12s\n', 'Method', 'dt', 'Steps', 'Max Error'); %[output:8a2be1be]
fprintf('%s\n', repmat('-', 1, 62)); %[output:2651a811]
fprintf('%-28s  %10.6f  %6d  %12.4e\n', 'Linear  + Explicit',   dt_LE, Nt_LE, err_LE); %[output:94e88109]
fprintf('%-28s  %10.6f  %6d  %12.4e\n', 'Linear  + Implicit',   dt_LI, Nt_LI, err_LI); %[output:17ceb3ef]
fprintf('%-28s  %10.6f  %6d  %12.4e\n', 'Quadratic + Explicit', dt_QE, Nt_QE, err_QE); %[output:0af00c6d]
fprintf('%-28s  %10.6f  %6d  %12.4e\n', 'Quadratic + Implicit', dt_QI, Nt_QI, err_QI); %[output:640bee98]
%%
%[text] ## Plot 1: Solutions at t\_final

x_fine = linspace(0, L, 500);
u_ref  = u_exact(x_fine, t_final);

figure('Position', [100 100 900 500]) %[output:2311becb]
plot(x_fine, u_ref, 'k-', 'LineWidth', 2.5); hold on; %[output:2311becb]
plot(x_LE, U_LE, 's-',  'LineWidth', 1.2, 'MarkerSize', 5); %[output:2311becb]
plot(x_LI, U_LI, 'o-',  'LineWidth', 1.2, 'MarkerSize', 5); %[output:2311becb]
plot(x_QE, U_QE, 'd-',  'LineWidth', 1.2, 'MarkerSize', 5); %[output:2311becb]
plot(x_QI, U_QI, '^-',  'LineWidth', 1.2, 'MarkerSize', 5); %[output:2311becb]
grid on; xlabel('x'); ylabel('u(x, t_{final})'); %[output:2311becb]
title(sprintf('All Methods at t = %.2f', t_final)); %[output:2311becb]
legend('Exact', ... %[output:group:54138c3d] %[output:2311becb]
       sprintf('Lin Explicit  (err=%.2e)', err_LE), ... %[output:2311becb]
       sprintf('Lin Implicit  (err=%.2e)', err_LI), ... %[output:2311becb]
       sprintf('Quad Explicit (err=%.2e)', err_QE), ... %[output:2311becb]
       sprintf('Quad Implicit (err=%.2e)', err_QI), ... %[output:2311becb]
       'Location', 'best'); %[output:group:54138c3d] %[output:2311becb]
%%
%[text] ## Plot 2: Pointwise Error at t\_final

figure('Position', [100 100 900 500]) %[output:0995d9f2]
subplot(1,2,1) %[output:0995d9f2]
plot(x_LE, abs(U_LE - u_exact(x_LE, t_final)), 's-', 'LineWidth', 1.2); hold on; %[output:0995d9f2]
plot(x_LI, abs(U_LI - u_exact(x_LI, t_final)), 'o-', 'LineWidth', 1.2); %[output:0995d9f2]
grid on; xlabel('x'); ylabel('|error|'); %[output:0995d9f2]
title('Linear Elements'); legend('Explicit', 'Implicit', 'Location', 'best'); %[output:0995d9f2]

subplot(1,2,2) %[output:0995d9f2]
plot(x_QE, abs(U_QE - u_exact(x_QE, t_final)), 'd-', 'LineWidth', 1.2); hold on; %[output:0995d9f2]
plot(x_QI, abs(U_QI - u_exact(x_QI, t_final)), '^-', 'LineWidth', 1.2); %[output:0995d9f2]
grid on; xlabel('x'); ylabel('|error|'); %[output:0995d9f2]
title('Quadratic Elements'); legend('Explicit', 'Implicit', 'Location', 'best'); %[output:0995d9f2]
sgtitle('Pointwise Error Distribution'); %[output:0995d9f2]
%%
%[text] ## Plot 3: Mesh Convergence (all four methods)

nel_list_lin  = [5 10 20 40 80 160];
nel_list_quad = [3  5 10 20 40  80];

err_LE_list = zeros(size(nel_list_lin));
err_LI_list = zeros(size(nel_list_lin));
err_QE_list = zeros(size(nel_list_quad));
err_QI_list = zeros(size(nel_list_quad));

for i = 1:numel(nel_list_lin)
    [~,~,~,~, err_LE_list(i)] = solve_linear(L, t_final, nel_list_lin(i), u_init, u_exact, 'explicit');
    [~,~,~,~, err_LI_list(i)] = solve_linear(L, t_final, nel_list_lin(i), u_init, u_exact, 'implicit');
end
for i = 1:numel(nel_list_quad)
    [~,~,~,~, err_QE_list(i)] = solve_quadratic(L, t_final, nel_list_quad(i), u_init, u_exact, 'explicit');
    [~,~,~,~, err_QI_list(i)] = solve_quadratic(L, t_final, nel_list_quad(i), u_init, u_exact, 'implicit');
end

h_lin  = L ./ nel_list_lin;
h_quad = L ./ nel_list_quad;

figure('Position', [100 100 900 500]) %[output:5d80a707]
loglog(h_lin,  err_LE_list, 's-',  'LineWidth', 1.5, 'MarkerSize', 8); hold on; %[output:5d80a707]
loglog(h_lin,  err_LI_list, 'o-',  'LineWidth', 1.5, 'MarkerSize', 8); %[output:5d80a707]
loglog(h_quad, err_QE_list, 'd-',  'LineWidth', 1.5, 'MarkerSize', 8); %[output:5d80a707]
loglog(h_quad, err_QI_list, '^-',  'LineWidth', 1.5, 'MarkerSize', 8); %[output:5d80a707]
% Reference slopes
loglog(h_lin, h_lin.^2 * (err_LE_list(1)/h_lin(1)^2), '--k', 'LineWidth', 0.8); %[output:5d80a707]
loglog(h_quad, h_quad.^4 * (err_QE_list(1)/h_quad(1)^4), ':k', 'LineWidth', 0.8); %[output:5d80a707]
grid on; xlabel('h (element size)'); ylabel('||error||_\infty'); %[output:5d80a707]
title('Mesh Convergence'); %[output:5d80a707]
legend('Lin Explicit', 'Lin Implicit', 'Quad Explicit', 'Quad Implicit', ... %[output:group:897b73e0] %[output:5d80a707]
       'O(h^2) ref', 'O(h^4) ref', 'Location', 'best'); %[output:group:897b73e0] %[output:5d80a707]
%%
%[text] ## Plot 4: CFL / Cost Comparison

fprintf('\n--- CFL & Cost Summary ---\n'); %[output:0d00d577]
fprintf('%-28s  CFL limit         dt used       Steps   Nodes\n', 'Method'); %[output:2dfd75a6]
fprintf('%s\n', repmat('-', 1, 80)); %[output:371b8282]

h_l = L/nel_lin;
h_q = L/nel_quad;
fprintf('%-28s  dt < h^2/2 = %.4e   %.4e   %5d   %5d\n', ... %[output:group:8b41fb6e] %[output:988398d2]
    'Linear Explicit',  h_l^2/2, dt_LE, Nt_LE, nel_lin+1); %[output:group:8b41fb6e] %[output:988398d2]
fprintf('%-28s  unconditional          %.4e   %5d   %5d\n', ... %[output:group:75d0165e] %[output:2f99ef27]
    'Linear Implicit',  dt_LI, Nt_LI, nel_lin+1); %[output:group:75d0165e] %[output:2f99ef27]
fprintf('%-28s  dt < h^2/7 = %.4e   %.4e   %5d   %5d\n', ... %[output:group:21002bab] %[output:3576286d]
    'Quadratic Explicit', h_q^2/7, dt_QE, Nt_QE, 2*nel_quad+1); %[output:group:21002bab] %[output:3576286d]
fprintf('%-28s  unconditional          %.4e   %5d   %5d\n', ... %[output:group:8f4c275c] %[output:9fbe8e88]
    'Quadratic Implicit', dt_QI, Nt_QI, 2*nel_quad+1); %[output:group:8f4c275c] %[output:9fbe8e88]

% Bar chart: steps vs accuracy
figure('Position', [100 100 900 400]) %[output:93aeec63]
subplot(1,2,1) %[output:93aeec63]
bar(categorical({'Lin Expl','Lin Impl','Quad Expl','Quad Impl'}), ... %[output:93aeec63]
    [Nt_LE, Nt_LI, Nt_QE, Nt_QI]); %[output:93aeec63]
ylabel('Time Steps'); title('Computational Cost (steps)'); %[output:93aeec63]
grid on; %[output:93aeec63]

subplot(1,2,2) %[output:93aeec63]
bar(categorical({'Lin Expl','Lin Impl','Quad Expl','Quad Impl'}), ... %[output:93aeec63]
    log10([err_LE, err_LI, err_QE, err_QI])); %[output:93aeec63]
ylabel('log_{10}(max error)'); title('Accuracy'); %[output:93aeec63]
grid on; %[output:93aeec63]
sgtitle('Cost vs Accuracy'); %[output:93aeec63]
%%
%[text] ## Plot 5: Time Evolution Comparison

t_check = [0 0.01 0.025 0.05 0.1];
x_fine  = linspace(0, L, 500);

figure('Position', [100 100 1000 600]) %[output:82657c05]
method_names = {'Linear Explicit', 'Linear Implicit', ...
                'Quadratic Explicit', 'Quadratic Implicit'};
nel_vals   = [nel_lin, nel_lin, nel_quad, nel_quad];
basis_type = {'linear', 'linear', 'quadratic', 'quadratic'};
time_type  = {'explicit', 'implicit', 'explicit', 'implicit'};

for m = 1:4
    subplot(2,2,m); hold on; %[output:82657c05]
    colors = parula(numel(t_check));
    leg_m = {};
    for ti = 1:numel(t_check)
        t_now = t_check(ti);
        if strcmp(basis_type{m}, 'linear')
            [xN, U_t] = solve_linear_at_t(L, t_now, nel_vals(m), u_init, time_type{m});
        else
            [xN, U_t] = solve_quadratic_at_t(L, t_now, nel_vals(m), u_init, time_type{m});
        end
        plot(xN, U_t, 'o-', 'Color', colors(ti,:), 'LineWidth', 1.2, 'MarkerSize', 3);
        plot(x_fine, u_exact(x_fine, t_now), '--', 'Color', colors(ti,:), 'LineWidth', 1.5);
        leg_m{end+1} = sprintf('FEM t=%.3f', t_now);
        leg_m{end+1} = sprintf('Exact t=%.3f', t_now);
    end
    grid on; xlabel('x'); ylabel('u');
    title(method_names{m});
    if m == 1
        legend(leg_m, 'Location', 'best', 'FontSize', 6);
    end
end
sgtitle('Time Evolution — All Methods'); %[output:82657c05]
%%
%[text] ## Helper: solve up to a specific time

function [xN, U] = solve_linear_at_t(L, t_target, nel, u_init, method)
    nn = nel + 1;
    xN = linspace(0, L, nn).';
    he = L / nel;
    K = zeros(nn); M = zeros(nn); M_diag = zeros(nn,1);
    for e = 1:nel
        nd = [e, e+1];
        K(nd,nd)   = K(nd,nd)   + (1/he)*[1 -1; -1 1];
        M(nd,nd)   = M(nd,nd)   + (he/6)*[2 1; 1 2];
        M_diag(nd) = M_diag(nd) + [he/2; he/2];
    end
    U = u_init(xN); U(1)=0; U(end)=0;
    if t_target == 0, return; end
    if strcmp(method,'explicit')
        dt = 0.8*he^2/2; Nt = ceil(t_target/dt); dt = t_target/Nt;
        for n=1:Nt, U = U+dt*((-K*U)./M_diag); U(1)=0; U(end)=0; end
    else
        dt = 0.005; Nt = round(t_target/dt);
        if Nt == 0, return; end
        dt = t_target/Nt;
        A = M+dt*K; A(1,:)=0; A(1,1)=1; A(end,:)=0; A(end,end)=1;
        for n=1:Nt, rhs=M*U; rhs(1)=0; rhs(end)=0; U=A\rhs; end
    end
end

function [xN, U] = solve_quadratic_at_t(L, t_target, nel, u_init, method)
    nn = 2*nel+1;
    xN = linspace(0, L, nn).';
    conn = [(1:2:2*nel-1).', (2:2:2*nel).', (3:2:2*nel+1).'];
    K = zeros(nn); M = zeros(nn); M_diag = zeros(nn,1);
    for e = 1:nel
        nd = conn(e,:); he = xN(nd(3))-xN(nd(1));
        K(nd,nd)   = K(nd,nd)   + (1/(3*he))*[7 -8 1; -8 16 -8; 1 -8 7];
        M(nd,nd)   = M(nd,nd)   + (he/30)*[4 2 -1; 2 16 2; -1 2 4];
        M_diag(nd) = M_diag(nd) + [he/6; 2*he/3; he/6];
    end
    U = u_init(xN); U(1)=0; U(end)=0;
    if t_target == 0, return; end
    he = L/nel;
    if strcmp(method,'explicit')
        dt = 0.8*he^2/7; Nt = ceil(t_target/dt); dt = t_target/Nt;
        for n=1:Nt, U = U+dt*((-K*U)./M_diag); U(1)=0; U(end)=0; end
    else
        dt = 0.005; Nt = round(t_target/dt);
        if Nt == 0, return; end
        dt = t_target/Nt;
        A = M+dt*K; A(1,:)=0; A(1,1)=1; A(end,:)=0; A(end,end)=1;
        for n=1:Nt, rhs=M*U; rhs(1)=0; rhs(end)=0; U=A\rhs; end
    end
end

